function applyGoldEffect(effect) {
  Object.entries(effect.institutional || {}).forEach(([key, value]) => { goldState.institutional[key] = (goldState.institutional[key] || 0) + value; });
  Object.entries(effect.issue || {}).forEach(([key, value]) => { goldState.issue[key] = (goldState.issue[key] || 0) + value; });
  Object.entries(effect.relationships || {}).forEach(([key, value]) => { goldState.relationships[key] = (goldState.relationships[key] || 0) + value; });
}
function inferGoldRoutes() {
  const i = goldState.issue; const r = goldState.relationships; const h = goldState.institutional;
  const route = (id, tendency, required, gates) => ({id, tendency, required, gates, eligible:false, status:'future-gate'});
  const routes = [
    route('state-service', (h.superiorTrust || 0) + (i.stateAuthority || 0), ['institutional history','official service encounter'], ['superiorTrust','officialServiceNetwork']),
    route('Slavophile network', (i.russianHistoricalParticularity || 0) + (i.religiousMoralRole || 0), ['issue combination','network access','future encounter'], ['russianHistoricalParticularity','slavophileNetwork']),
    route('Belinsky / legal Westernizer criticism', (i.literaturePublicRole || 0) + (i.socialReform || 0), ['public-literature issue','actual correspondence'], ['literaturePublicRole','belinskyNetwork']),
    route('Herzen / exilic critical publishing', (i.pressFreedom || 0) + (i.politicalRiskTolerance || 0), ['press issue','future access route'], ['pressFreedom','herzenNetwork']),
    route('Petrashevsky / dossier-risk', (i.associationPrivacy || 0) + (i.surveillanceEvidenceThreshold || 0), ['association issue','dossier history','actual encounter'], ['associationPrivacy','petrashevskyNetwork'])
  ];
  return {completedScenes:goldState.completedScenes.length, routes, openPathCount:routes.filter(candidate => candidate.gates.some(gate => !(r[gate] || h[gate] || i[gate]))).length};
}
